const fs = require('node:fs');
const crypto = require('node:crypto');
const dir = 'products/distribution/sqlite-lemonsqueezy-fit';
const source = `${dir}/raw/fees.html`;
const html = fs.readFileSync(source, 'utf8');
const text = html.replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&#160;|&#xA0;/gi, ' ').replace(/\s+/g, ' ');
const match = /5\s*%\s*\+\s*\$\s*0\.50\b/.exec(text);
const money = cents => (cents / 100).toFixed(2);
const result = {
  source: 'https://docs.lemonsqueezy.com/help/getting-started/fees',
  source_file: source,
  source_sha256: crypto.createHash('sha256').update(html).digest('hex'),
  status: match ? 'illustrative_base_fee_only' : 'base_fee_text_not_matched',
  passage: match ? text.slice(Math.max(0, match.index - 100), match.index + match[0].length + 120) : null,
  rows: match ? [1200, 1900, 2900].map(price => {
    const fee = price / 20 + 50;
    return { price_usd: money(price), base_fee_usd: money(fee), amount_after_base_fee_usd: money(price - fee) };
  }) : [],
  limits: 'Prices are scenarios. Read the passage in the original before using these rows. Additional transaction and payout charges, taxes, refunds, FX and costs are outside the calculation. No payout, sale or profit was verified.'
};
if (match && result.rows[1].amount_after_base_fee_usd !== '17.55') throw new Error('Unexpected base fee calculation');
fs.mkdirSync(dir, { recursive: true });
const output = `${dir}/director-base-fee-scenarios.json`;
fs.writeFileSync(output, JSON.stringify(result, null, 2) + '\n');
console.log(JSON.stringify({ output, status: result.status, rows: result.rows.length }));
